SELECT COUNT(1) FROM orders_rel_chinaumspay_division reldivision
INNER JOIN orders_normal_orders o ON reldivision.order_id = o.order_id
WHERE reldivision.status = '0' AND o.order_auto_close_aftersales_time <= #{now}

SELECT IFNULL(SUM(ad.refund_fee), 0) FROM aftersales_detail ad
WHERE ad.company_id = #{companyId} AND ad.order_id = #{orderId}
AND ad.aftersales_status IN (0, 5, 1, 2)
